package cn.finalscompass.controller;import cn.finalscompass.ai.runtime.agent.AiRuntimeDispatchService;import cn.finalscompass.service.AuthService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.HttpHeaders;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.util.List;import java.util.Map;
@RestController @RequestMapping("/api/ai-center/dispatch") public final class AiRuntimeDispatchController{private final AuthService auth;private final AiRuntimeDispatchService service;public AiRuntimeDispatchController(AuthService auth,AiRuntimeDispatchService service){this.auth=auth;this.service=service;}@PostMapping public AiRuntimeDispatchService.Run start(HttpServletRequest r,@RequestBody AiRuntimeDispatchService.Start b){return service.start(auth.current(r).id(),b);}@GetMapping("/{key}")public AiRuntimeDispatchService.Run view(HttpServletRequest r,@PathVariable String key){return service.view(auth.current(r).id(),key);}@DeleteMapping("/{key}")public AiRuntimeDispatchService.Run cancel(HttpServletRequest r,@PathVariable String key){return service.cancel(auth.current(r).id(),key);}@PostMapping("/{key}/participants")public AiRuntimeDispatchService.Run report(HttpServletRequest r,@PathVariable String key,@RequestBody AiRuntimeDispatchService.Report b){return service.report(auth.current(r).id(),key,b);}@GetMapping("/{key}/artifacts")public List<Map<String,Object>> artifacts(HttpServletRequest r,@PathVariable String key){return service.artifacts(auth.current(r).id(),key);}@GetMapping("/{key}/artifacts/{artifactId}")public ResponseEntity<byte[]> artifact(HttpServletRequest r,@PathVariable String key,@PathVariable long artifactId){Map<String,Object>row=service.artifact(auth.current(r).id(),key,artifactId);Path path=Paths.get(String.valueOf(row.get("storage_path"))).toAbsolutePath().normalize();if(!path.startsWith(Paths.get("uploads").toAbsolutePath().normalize()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Artifact not found");try{byte[]content=Files.readAllBytes(path);return ResponseEntity.ok().contentType(MediaType.parseMediaType(String.valueOf(row.getOrDefault("content_type","application/octet-stream")))).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+row.get("file_name")+"\"").body(content);}catch(Exception e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Artifact not found");}}}
